require "rails_helper"

RSpec.describe Timekeeping::WriteSteps do
  it "refuses a bad stored source with a 409 that names the field but never echoes the stored value" do
    stored_value = "legacy-token-sk_live_do_not_echo"
    entry = Entry.create!(company_id: 1, user_id: 7, project_id: 3, work_date: "2026-03-02", duration: 90.0,
                          note: "kept", bill_status: "unbilled", source: "manual", source_metadata: {})
    # A checkpoint load can store a value the snapshot rules refuse.
    entry.update_column(:source, stored_value)
    row = described_class.reserved_rows(1, [entry.id]).fetch(entry.id)

    error = nil
    ApplicationRecord.transaction do
      described_class.write_outbox([row], 1)
    rescue Timekeeping::WriteSteps::UnpublishableRows => raised
      error = raised
    end

    expect(error).to be_a(Timekeeping::WriteSteps::UnpublishableRows)
    expect(OutboxSnapshot.count).to eq(0)
    outcome = error.outcome
    expect(outcome.status).to eq(409)
    expect(JSON.parse(outcome.body)).to eq(
      "reason" => "unpublishable_entry", "entries" => [{ "entry_id" => entry.id, "fields" => ["source"] }]
    )
    # The answer and the error text name fields only, so a stored value never leaves in a response or a log line.
    expect(outcome.body).not_to include(stored_value)
    expect(error.message.to_s).not_to include(stored_value)
  end
end

