  # A partial insert would leave the outbox out of step with storage, so the valid row must not go in alone.
  it "write_outbox raises UnpublishableRows and inserts no row when one stored row of the batch is bad" do
    valid = timekeeping_arrange.entry(company:, user: owner, project:)
    bad = timekeeping_arrange.entry(company:, user: owner, project:)
    Entry.find(bad).update_column(:bill_status, "paid")
    rows = described_class.reserved_rows(company, [valid, bad])

    expect { described_class.write_outbox([rows.fetch(valid), rows.fetch(bad)], timekeeping_arrange.current_generation) }
      .to raise_error(Timekeeping::WriteSteps::UnpublishableRows)
    expect(OutboxSnapshot.count).to eq(0)
    expect(Entry.find(bad).bill_status).to eq("paid")
  end
