RSpec.describe Timekeeping::WriteSteps do
  include_context "timekeeping entry writes"

  let(:company) { timekeeping_arrange.company }
  let(:user) { timekeeping_arrange.user(company:, role: "employee") }
  let(:project) { timekeeping_arrange.project(company:) }

  it "still inserts one outbox row per valid stored entry, equal to OutboxFields.row" do
    first = timekeeping_arrange.entry(company:, user:, project:, duration: 0.0)
    second = timekeeping_arrange.entry(company:, user:, project:, source_metadata: { "rate" => "1.5" })
    rows = described_class.reserved_rows(company, [first, second])

    described_class.write_outbox([rows.fetch(first), rows.fetch(second)], 1)

    expect(OutboxSnapshot.where(id: [first, second]).count).to eq(2)
    expect(OutboxSnapshot.where(id: first).count).to eq(1)
    expected = Timekeeping::OutboxFields.row(rows.fetch(second), generation: 1)
    stored = OutboxSnapshot.find_by!(id: second)
    expect([stored.source, stored.source_metadata, stored.version, stored.generation, stored.locked])
      .to eq(expected.values_at("source", "source_metadata", "version", "generation", "locked"))
  end
end

