require "rails_helper"

RSpec.describe Timekeeping::WriteSteps do
  include_context "timekeeping entry writes"

  let(:company) { timekeeping_arrange.company }

  # The bad row comes last, so a check that inserted row by row, or that checked only the first row,
  # would already have queued the valid ones.
  it "inserts no outbox row for the valid entries ahead of a bad one in the same call" do
    user = timekeeping_arrange.user(company:, role: "employee")
    project = timekeeping_arrange.project(company:)
    valid_ids = Array.new(2) { timekeeping_arrange.entry(company:, user:, project:) }
    bad = timekeeping_arrange.entry(company:, user:, project:)
    Entry.find(bad).update_column(:bill_status, "paid")
    rows = described_class.reserved_rows(company, valid_ids + [bad])
    before = OutboxSnapshot.count

    expect do
      ApplicationRecord.transaction do
        described_class.write_outbox((valid_ids + [bad]).map { |id| rows.fetch(id) }, timekeeping_arrange.current_generation)
      end
    end.to raise_error(Timekeeping::WriteSteps::UnpublishableRows)
    expect(OutboxSnapshot.count).to eq(before)
  end
end
